CREATE TABLE IF NOT EXISTS public.erp_permission_catalog (key text, description text, created_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS public.erp_role_permissions (role text, permission_key text, allowed boolean);
CREATE TABLE IF NOT EXISTS public.erp_sale_test_payments (id uuid, sale_id uuid, payment_method_id uuid, amount numeric(12,2), status text, channel text, scheduled_for timestamp with time zone, paid_at timestamp with time zone, provider_reference text, confirmed_by uuid, created_by uuid, created_at timestamp with time zone, test_only boolean, method_code text, reference text);
CREATE TABLE IF NOT EXISTS public.erp_sales (id uuid, customer_id uuid, branch_id uuid, created_by uuid, status text, created_at timestamp with time zone, updated_at timestamp with time zone, confirmed_at timestamp with time zone, payment_method_id uuid, payment_term_id uuid, customer_snapshot jsonb, branch_snapshot jsonb, seller_snapshot text, notes text, discount_reason text, subtotal numeric(12,2), discount_amount numeric(12,2), shipping_charged numeric(12,2), shipping_actual_cost numeric(12,2), total numeric(12,2), draft_key uuid, shipping_confirmed boolean, cancelled_at timestamp with time zone, cancelled_by uuid, cancellation_reason text, order_number bigint, first_product_at timestamp with time zone, is_test boolean, test_finalize_key uuid, test_confirmed_by uuid, finalize_key uuid, internal_notes text);
CREATE TABLE IF NOT EXISTS public.erp_user_permission_overrides (user_id uuid, permission_key text, allowed boolean, reason text, assigned_by uuid, updated_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS public.erp_user_profiles (user_id uuid, username text, display_name text, role text, active boolean, can_view_financial_metrics boolean, created_at timestamp with time zone, updated_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS public.products (id uuid, code text, sku text, name text, description text, category text, brand text, model_phone text, type text, current_cost numeric(12,2), managerial_cost numeric(12,2), sale_price numeric(12,2), controls_inventory boolean, current_inventory numeric(12,2), min_inventory numeric(12,2), max_inventory numeric(12,2), stock_verified boolean, image_url text, source_tab text, active boolean, b2b_site_visible boolean, notes text, created_at timestamp with time zone, updated_at timestamp with time zone);
